import { useQuery } from '@tanstack/react-query';
import axios from 'axios';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { API_URLS } from '~/shared/api/api-urls';
import { TokenItemType, WalletUseYN } from '~/shared/api/dtos/enums';
import { queries } from '~/shared/api/query-keys';
import { resultify } from '~/shared/lib/utils/resultify';

const createWalletTokenList = ({ amt, bankCd }: { amt?: number | null; bankCd?: string | null }): TokenItem[] => {
  return [
    {
      id: '0',
      type: TokenItemType.DC1,
      amt: amt ?? 0,
      bankCd: bankCd ?? '',
    },
  ];
};

const mapWallet = (wallet: UserWalletResponse): UserWalletResponse => ({
  ...wallet,
  isWalletBlocked: wallet.useYn === WalletUseYN.블랙리스트,
  tokenList: createWalletTokenList({
    amt: wallet.acnutnoBlce,
    bankCd: wallet.bankCd,
  }),
});

export const getCstmrWalletList = async () => {
  const data = await resultify(axios.get<UserWalletResponse[]>(API_URLS.cstmrWalletList));
  return data.map(mapWallet);
};

export const useGetCstmrWalletListQuery = () => {
  return useQuery({
    queryKey: queries.cstr.cstmrWalletList.queryKey,
    queryFn: () => getCstmrWalletList(),
  });
};
